const {chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');
const BASE=process.env.MX_AUDIT_URL||'http://127.0.0.1:5183';const CHROME=process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
(async()=>{const browser=await chromium.launch({executablePath:CHROME,headless:true});const page=await browser.newPage({viewport:{width:1100,height:1200}});let errors=[];page.on('pageerror',e=>errors.push(String(e)));const out='docs/styles/style2/implementation/round1/screens';fs.mkdirSync(out,{recursive:true});const rows=[];
for(const [scene,w,h]of [['media-voice',440,782],['media-video',440,782],['raise',440,782],['settings',440,782],['figma',440,956],['figma',375,500],['figma',320,400],['insurance-single',440,782],['insurance-multi',440,782],['report',440,782],['history',440,782],['chat',440,782],['menu',440,782],['bring-wallet',440,782],['profile',440,782],['settings-quick',440,782],['settings-system',440,782],['squid-result-figma',440,782],['room-details',440,782]]){
await page.goto(BASE+'/tests/fixtures/layout-audit.html?'+new URLSearchParams({skin:'style2',layout:'balanced',scene,width:w,height:h}));await page.locator('#audit-stage[data-ready=true]').waitFor({timeout:60000});await page.waitForTimeout(150);await page.locator('#audit-stage').screenshot({path:`${out}/${scene}-${w}x${h}.png`});rows.push({scene,w,h,errors:errors.splice(0),nodes:await page.evaluate(()=>Array.from(document.querySelectorAll('.mx-nav-button,.mx-nav-icon,.mx-menu,.mx-menu-panel,.mx-raise-confirm,.mx-raise-range')).filter(e=>e.checkVisibility()).map(e=>({c:e.className,t:e.textContent,r:e.getBoundingClientRect().toJSON(),bg:getComputedStyle(e).backgroundSize,flex:getComputedStyle(e).flexShrink})))})}
fs.writeFileSync(out+'/results.json',JSON.stringify(rows,null,2));console.log(rows.map(r=>({scene:r.scene,size:[r.w,r.h],errors:r.errors,nav:r.nodes.filter(n=>n.c==='mx-nav-button').length})));await browser.close()})();
